package io.knowledgebrain.activity;
import java.util.*;import java.net.*;import java.net.http.*;import java.time.Duration;import tools.jackson.databind.json.JsonMapper;
final class ActivitySnapshot {
 private ActivitySnapshot planning,content,knowledge,integration;private final String group;
 record Item(UUID eventId,String topic,String payload){}record Page(UUID through,UUID nextAfter,List<Item> items){}
 private final URI origin;private final HttpClient http;private final String key;private final JsonMapper json=JsonMapper.builder().build();
 ActivitySnapshot(String origin,String trust,String key,String planningOrigin,String planningKey)throws Exception{this(origin,trust,key,"learning");planning=new ActivitySnapshot(planningOrigin,trust,planningKey,"planning");}
 ActivitySnapshot(String origin,String trust,String key,String planningOrigin,String planningKey,String contentOrigin,String contentKey)throws Exception{this(origin,trust,key,planningOrigin,planningKey);content=new ActivitySnapshot(contentOrigin,trust,contentKey,"content");}
 ActivitySnapshot(String origin,String trust,String key,String planningOrigin,String planningKey,String contentOrigin,String contentKey,String knowledgeOrigin,String knowledgeKey)throws Exception{this(origin,trust,key,planningOrigin,planningKey,contentOrigin,contentKey);knowledge=new ActivitySnapshot(knowledgeOrigin,trust,knowledgeKey,"knowledge");}
 ActivitySnapshot(String origin,String trust,String key,String planningOrigin,String planningKey,String contentOrigin,String contentKey,String knowledgeOrigin,String knowledgeKey,String integrationOrigin,String integrationKey)throws Exception{this(origin,trust,key,planningOrigin,planningKey,contentOrigin,contentKey,knowledgeOrigin,knowledgeKey);integration=new ActivitySnapshot(integrationOrigin,trust,integrationKey,"integration");}
 ActivitySnapshot(String origin,String trust,String key)throws Exception{this(origin,trust,key,"learning");}
 private ActivitySnapshot(String origin,String trust,String key,String group)throws Exception{this.group=group;this.origin=ActivityHttp.origin(origin);http=ActivityHttp.client(trust);if(!key.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Scoped canonical key required");this.key=key;}
 Page page(UUID after,UUID through){String uri="/internal/"+group+"/activity-events"+(after!=null||through!=null?"?":"")+(after!=null?"after="+after:"")+(through!=null?(after!=null?"&":"")+"through="+through:"");var response=ActivityHttp.send(http,HttpRequest.newBuilder(origin.resolve(uri)).timeout(Duration.ofSeconds(8)).header("Authorization","Bearer "+key).GET().build(),8388608);if(response.statusCode()!=200)throw new IllegalStateException("Canonical activity recovery unavailable");var p=json.readValue(response.body(),Page.class);if(p==null||p.items()==null||p.items().size()>5||through!=null&&!through.equals(p.through())||p.through()==null&&(!p.items().isEmpty()||p.nextAfter()!=null))throw ActivityEvent.invalid();UUID last=after;if(p.through()!=null)ActivityEvent.id(p.through().toString());for(var item:p.items()){var e=ActivityEvent.decode(item.topic(),Base64.getDecoder().decode(item.payload()));if(!ActivityEvent.group(e.kind()).equals(group)||!e.eventId().equals(item.eventId())||p.through()==null||item.eventId().toString().compareTo(p.through().toString())>0||last!=null&&item.eventId().toString().compareTo(last.toString())<=0)throw ActivityEvent.invalid();last=item.eventId();}if(p.nextAfter()!=null&&(p.items().size()!=5||!p.nextAfter().equals(last)))throw ActivityEvent.invalid();return p;}
 void backfill(ActivityStore store){backfill(store,integration!=null?List.of(this,planning,content,knowledge,integration):knowledge!=null?List.of(this,planning,content,knowledge):content!=null?List.of(this,planning,content):planning==null?List.of(this):List.of(this,planning));}
 static void backfill(ActivityStore store,List<ActivitySnapshot> sources){store.backfillStarted();for(var source:sources)source.scan(store);store.seeded();}
 private void scan(ActivityStore store){long rows=0;org.slf4j.LoggerFactory.getLogger(getClass()).info("activity_backfill source={} outcome=STARTED",group);UUID after=null,through=null;do{var p=page(after,through);through=p.through();for(var item:p.items())store.stage(item.topic(),Base64.getDecoder().decode(item.payload()));rows+=p.items().size();after=p.nextAfter();}while(after!=null);org.slf4j.LoggerFactory.getLogger(getClass()).info("activity_backfill source={} outcome=COMPLETED rows={}",group,rows);}
}
